head.script:
scwin.screenId = "jldstf32201";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
    /* sdd-asis-lifecycle:end */
};


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

scwin.pathname = undefined; try { scwin.pathname = /* sdd-asis-lifecycle:begin pathname — as-is 원문 본문(전환 이관 · 포팅 적용됨) */location.pathname/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf32201' }); }

scwin.qry = undefined; try { scwin.qry = /* sdd-asis-lifecycle:begin qry — as-is 원문 본문(전환 이관 · 포팅 적용됨) */location.search/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf32201' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf32201.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_61_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_61_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_61_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        IsurcdSearch2('ISU_CD','COM_NM',315,155)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf32201.img_61_onclick' }); }
};

/**
