/**
 * @event
 * @name scwin.btn_Reset_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Reset_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Reset_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.reset()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf32201.btn_Reset_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Cal2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Cal2_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Cal2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.cal2()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf32201.btn_Cal2_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Cal2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Cal2 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal2", unresolved: "action:self_submit:tx_fn_Cal2" };
};

/**
 * @method
 * @name scwin.tx_fn_ExcelDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ExcelDown = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_ExcelDownReq") ? $c.util.getComponent("dma_ExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.reset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reset = async function () {
    /* sdd-asis-lifecycle:begin fn_Reset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    $c.util.getComponent("cal_decisionDate").setValue("");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    const p = {}; p["ISU_CD"] = $c.util.getComponent("dma_Cal2Req").get("ISU_CD"); p["COM_NM"] = $c.util.getComponent("ipt_COM_NM_2").getValue(); p["SCREN_ID"] = $c.util.getComponent("dma_Cal2Req").get("SCREN_ID"); p["SCREN_PROCES_TP_CD"] = $c.util.getComponent("dma_Cal2Req").get("SCREN_PROCES_TP_CD"); p["decisionDate"] = $c.util.getComponent("cal_decisionDate").getValue(); p["gubun"] = $c.util.getComponent("ipt_gubun").getValue(); p["decisionAmount"] = $c.util.getComponent("ipt_decisionAmount").getValue(); p["decisionMoney"] = $c.util.getComponent("ipt_decisionMoney").getValue(); p["restDate"] = $c.util.getComponent("ipt_restDate").getValue(); p["cumulationAmount"] = $c.util.getComponent("ipt_cumulationAmount").getValue(); p["cumulationMoney"] = $c.util.getComponent("ipt_cumulationMoney").getValue(); p["isCompletion"] = $c.util.getComponent("ipt_isCompletion").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldstf32201/jldstf32201.xml', p);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.cal2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cal2 = async function () {
    /* sdd-asis-lifecycle:begin fn_Cal2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    await scwin.tx_fn_Cal2();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkNum
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkNum = function () {
    /* sdd-asis-lifecycle:begin checkNum — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 8 || event.keyCode == 46) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) {
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param tableID
 * @returns
 * @hidden N
*/
scwin.excelDown = async function (tableID) {
    /* sdd-asis-lifecycle:begin fn_ExcelDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (tableID.rows.length == 0) {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent('dma_Cal2Req').set('excelData', tableID.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    scwin.form_frmISU_CD.action = "/bizspt/excelDown.jsp";
    await scwin.tx_fn_ExcelDown();
    /* sdd-asis-lifecycle:end */
};
